function respawn(){state.hp=playerStats().maxHp;state.gold=Math.max(0,state.gold-10);player.x=950;player.y=690;player.invuln=1.4;notify('El frío te devuelve al santuario. Perdiste 10 monedas.');save()}
function addXp(n){state.xp+=n;while(state.xp>=state.level*100){state.xp-=state.level*100;state.level++;state.points+=2;state.hp=playerStats().maxHp;state.energy=playerStats().maxEn;notify(`¡Nivel ${state.level}! Has ganado 2 puntos de atributo.`)}save()}
function killEnemy(e){e.dead=true;state.kills++;let xp=e.boss?180:e.name.includes('Samurái')?32:20,gold=e.boss?150:Math.floor(5+Math.random()*11);state.gold+=gold;addXp(xp);floatText(e.x,e.y-25,`+${xp} EXP · ◈${gold}`,'#e5cd8d');for(let i=0;i<13;i++)particles.push({x:e.x,y:e.y,vx:rand(-60,60),vy:rand(-100,30),gravity:80,life:rand(.3,.8),color:e.boss?'#cf7556':'#b9d1c9',size:rand(2,5)});if(e.name.toLowerCase().includes('lobo')){state.quests.wolves++;updateQuest()}if(e.boss){state.defeated.push('oni');state.quests.oni=2;state.completed.push('oni');state.unlocked=[...new Set([...state.unlocked,2,3])];notify('El Oni cae. Los caminos hacia la aldea y el templo se abren.');document.getElementById('bossHud').classList.add('hidden');boss=null;updateQuest();save()}else notify(`+${gold} monedas · ${xp} EXP`)}
function attack(heavy=false){if(player.attackCd>0||player.dodge>0||gamePaused)return;if(heavy){if(player.heavyCd>0||state.energy<12){notify(state.energy<12?'Energía insuficiente':'');return}player.heavyCd=.9;state.energy-=12;player.attack=.42}else{player.attackCd=.34;state.energy=Math.min(playerStats().maxEn,state.energy+2);player.attack=.25}const range=heavy?95:70,damage=playerStats().damage*(heavy?2.1:1);let hit=false;for(const e of enemies){if(e.dead)continue;let vx=e.x-player.x,vy=e.y-player.y,d=Math.hypot(vx,vy),dot=(vx*player.face.x+vy*player.face.y)/Math.max(d,1);if(d<range+e.r&&dot>-.25){e.hp-=damage;e.flash=.2;e.x+=player.face.x*(heavy?35:13);e.y+=player.face.y*(heavy?35:13);floatText(e.x,e.y-20,`−${Math.round(damage)}`,'#f0d091');hit=true;if(e.hp<=0)killEnemy(e)}}for(let i=0;i<(heavy?12:7);i++){let a=Math.atan2(player.face.y,player.face.x)+rand(-.85,.85),rr=rand(22,75);particles.push({x:player.x+Math.cos(a)*rr,y:player.y+Math.sin(a)*rr,vx:Math.cos(a)*rand(20,85),vy:Math.sin(a)*rand(20,85),gravity:0,life:rand(.12,.28),color:heavy?'#e7aa62':'#e5e2c9',size:rand(2,4)})}if(hit&&Math.random()<.12)state.inv.push({name:'Hierba medicinal',kind:'Consumible',rarity:'Común',count:1,desc:'Restaura 20 puntos de salud.'});}
