function heal(){if(state.potions<=0){notify('No te quedan brebajes.');return}if(state.hp>=playerStats().maxHp){notify('Tu salud ya está al máximo.');return}state.potions--;state.hp=Math.min(playerStats().maxHp,state.hp+45);notify('Brebaje consumido · +45 salud');save()}
function nearTarget(){let best=null,bd=80;for(const n of npcs()){let d=Math.hypot(n.x-player.x,n.y-player.y);if(d<bd){bd=d;best={...n,d}}}for(const d of decor){if(['cave','shrine'].includes(d.type)){let dd=Math.hypot(d.x-player.x,d.y-player.y);if(dd<70&&dd<bd){bd=dd;best={type:d.type,x:d.x,y:d.y,d:dd}}}}for(const p of portals()){let dd=Math.hypot(p.x-player.x,p.y-player.y);if(dd<75&&dd<bd){bd=dd;best={...p,type:'portal',d:dd}}}return best}

