function npcs(){if(state.region===0)return [{name:'Daichi',x:1050,y:630,icon:'弓',role:'hunter'},{name:'Yuna',x:780,y:420,icon:'巫',role:'guide'},{name:'Ren',x:1190,y:890,icon:'商',role:'merchant'},{name:'Hana',x:510,y:850,icon:'花',role:'herbalist'}];if(state.region===1)return [{name:'Monje Sora',x:680,y:520,icon:'僧',role:'forest'},{name:'Kitsune',x:1240,y:850,icon:'狐',role:'fox'}];if(state.region===2)return [{name:'Akari',x:720,y:620,icon:'灯',role:'village'},{name:'Ren',x:1100,y:480,icon:'商',role:'merchant'}];return [{name:'Monje Sora',x:900,y:520,icon:'僧',role:'lore'}]}
function portals(){return [{x:1800,y:680,to:1,label:'Sendero del bosque'},{x:100,y:680,to:0,label:'Paso de montaña'},...(state.region===1?[{x:1800,y:680,to:2,label:'Camino a Kagehama'}]:[]),...(state.region===2?[{x:1800,y:680,to:3,label:'Escalinata sagrada'}]:[]),...(state.region===3?[{x:1800,y:680,to:4,label:'Marjal de los lamentos'}]:[]),...(state.region===4?[{x:1800,y:680,to:5,label:'Puertas del Reino'}]:[]),...(state.region===5?[{x:100,y:680,to:4,label:'Regresar al marjal'}]:[]) ]}
function interact(){if(gamePaused)return;let t=nearTarget();if(!t){if(state.region===0&&Math.hypot(player.x-950,player.y-1120)<95){startBoss()}return}if(t.type==='portal'){if(!state.unlocked.includes(t.to)){notify('El camino está sellado. Avanza en tu historia.');return}travel(t.to);return}if(t.type==='cave'){notify('La cueva está oscura. Busca una linterna cerca del campamento.');return}if(t.type==='shrine'){if(state.region===0&&!state.defeated.includes('oni')){startBoss();return}state.hp=playerStats().maxHp;state.energy=playerStats().maxEn;save();notify('Santuario: salud y energía restauradas.');return}talk(t)}
function travel(to){state.region=to;state.discoveries=[...new Set([...state.discoveries,to])];state.x=to===0?1600:to===5?220:120;state.y=680;player.x=state.x;player.y=state.y;makeWorld();notify(`Llegaste a ${regions[to].name}`);save()}
function startBoss(){if(state.defeated.includes('oni')){notify('El santuario guarda silencio.');return}if(boss)return;let e=enemy('Oni de hielo',950,1120,0);e.boss=true;e.aggro=true;e.speed=64;enemies.push(e);boss=e;document.getElementById('bossHud').classList.remove('hidden');document.getElementById('bossName').textContent='ONI DE HIELO';notify('Un rugido sacude el santuario…')}
function talk(n){dialogueTarget=n;const dlg=document.getElementById('dialogue');dlg.classList.remove('hidden');gamePaused=true;const name=document.getElementById('dialogueName'),text=document.getElementById('dialogueText'),portrait=document.getElementById('dialoguePortrait'),choices=document.getElementById('dialogueChoices');name.textContent=n.name.toUpperCase();portrait.textContent=n.icon;choices.innerHTML='';let line='',options=[];
 if(n.role==='hunter'){if(state.quests.wolves>=5&&!state.completed.includes('wolves')){line='Cinco lobos menos en el paso. La montaña puede respirar otra vez. Toma esto; lo encontré junto a una vieja tumba.';options=[['Entregar la cacería',()=>{state.completed.push('wolves');state.gold+=60;addXp(70);state.inv.push({name:'Piel de lobo',kind:'Material',rarity:'Poco común',count:1,desc:'Piel espesa, marcada por escarcha.'});state.unlocked=[...new Set([...state.unlocked,2])];notify('Misión completada · +60 monedas');updateQuest();save()}]]}else if(state.quests.wolves>0){line=`Cinco lobos acechan el camino. Has abatido ${Math.min(5,state.quests.wolves)} de 5. No te confíes; cazan en manada.`}else{line='Las huellas se multiplican hacia el norte. Cinco lobos rondan el paso. Ayúdame a despejar el sendero.';options=[['Aceptar: caza de lobos',()=>{state.quests.wolves=0;state.questWolfActive=true;notify('Nueva misión: Cacería en la nieve');updateQuest();save()}]]}}
 else if(n.role==='guide'){line=state.defeated.includes('oni')?'La ruta hacia Kagehama está abierta. Pero no todo lo que despierta tiene cuerpo…':'Soy Yuna, guardiana de este santuario. Algo enorme se mueve entre las ruinas. Afila tu hoja y vuelve cuando estés preparado.';options=[['¿Qué ocurrió aquí?',()=>{line='La nieve llegó en pleno verano. Luego las campanas sonaron bajo tierra. Nadie recuerda quién las hizo callar.';text.textContent=line}]]}
 else if(n.role==='merchant'){line='Mis provisiones no son baratas, pero sí honestas. ¿Necesitas algo para el camino?';options=[['Comprar brebaje · 18 monedas',()=>{if(state.gold>=18){state.gold-=18;state.potions++;notify('Brebaje añadido a la bolsa.');save()}else notify('No tienes suficientes monedas.')}],['Ver equipo',()=>openPanel('inventory')]]}
