 // distant mountain silhouettes
 for(let layer=0;layer<3;layer++){ctx.beginPath();ctx.moveTo(0,520+layer*55);for(let x=0;x<=W;x+=110){let y=430+layer*95+Math.sin(x*.006+layer*3)*45+Math.sin(x*.017+layer)*22;ctx.lineTo(x,y)}ctx.lineTo(W,0);ctx.lineTo(0,0);ctx.closePath();ctx.fillStyle=['#a2b3b0','#718781','#536966'][layer];ctx.globalAlpha=[.42,.4,.48][layer];ctx.fill();ctx.globalAlpha=1}
 if(state.region===0){for(let i=0;i<14;i++){let x=i*155+40,y=360+(i%4)*19;ctx.fillStyle='#d9e3df';ctx.beginPath();ctx.moveTo(x-95,y+170);ctx.lineTo(x,y-20-(i%3)*26);ctx.lineTo(x+95,y+170);ctx.fill();ctx.fillStyle='#71858a';ctx.beginPath();ctx.moveTo(x-20,y+20);ctx.lineTo(x,y-20-(i%3)*26);ctx.lineTo(x+32,y+51);ctx.lineTo(x+4,y+38);ctx.lineTo(x-3,y+80);ctx.closePath();ctx.fill()}}
 // serpentine path painted as wide organic strokes
 ctx.save();ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(70,700);ctx.bezierCurveTo(340,720,350,930,630,900);ctx.bezierCurveTo(880,870,780,560,1040,590);ctx.bezierCurveTo(1280,620,1130,980,1480,900);ctx.bezierCurveTo(1630,870,1730,760,1900,770);ctx.strokeStyle='#25302d';ctx.lineWidth=160;ctx.stroke();ctx.beginPath();ctx.moveTo(70,700);ctx.bezierCurveTo(340,720,350,930,630,900);ctx.bezierCurveTo(880,870,780,560,1040,590);ctx.bezierCurveTo(1280,620,1130,980,1480,900);ctx.bezierCurveTo(1630,870,1730,760,1900,770);ctx.strokeStyle=t.path;ctx.globalAlpha=.72;ctx.lineWidth=108;ctx.stroke();ctx.restore();
 // snowbanks / mossy flecks
 for(let i=0;i<120;i++){let x=(i*163+71)%W,y=(i*277+83)%H;ctx.globalAlpha=.06+((i%5)*.02);ctx.fillStyle=state.region===0?'#f4f4ed':'#d4cda9';ctx.beginPath();ctx.ellipse(x,y,18+(i%3)*8,2+(i%4),Math.sin(i)*.3,0,TAU);ctx.fill()}ctx.globalAlpha=1;
 // frozen lake
 if(state.region===0){const lake=ctx.createRadialGradient(1480,350,20,1480,350,185);lake.addColorStop(0,'#a9ccd1');lake.addColorStop(1,'#476b77');ctx.fillStyle=lake;ctx.beginPath();ctx.ellipse(1480,350,185,90,-.25,0,TAU);ctx.fill();ctx.strokeStyle='#e2eeee';ctx.globalAlpha=.4;ctx.lineWidth=2;ctx.stroke();ctx.globalAlpha=1}}

