function drawRuin(o){ctx.save();ctx.translate(o.x,o.y);if(o.type==='dead'){ctx.strokeStyle='#3b3c34';ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(0,15);ctx.lineTo(-4,-45);ctx.moveTo(-3,-18);ctx.lineTo(-31,-41);ctx.moveTo(-3,-28);ctx.lineTo(25,-50);ctx.stroke()}else{ctx.fillStyle='#444741';ctx.fillRect(-24,-4,48,20);ctx.fillRect(-19,-28,12,25);ctx.fillRect(8,-38,11,35)}ctx.restore()}
function drawNpc(n){ctx.save();ctx.translate(n.x,n.y+Math.sin(state.time*2+n.x)*2);ctx.fillStyle='#0a1112';ctx.beginPath();ctx.ellipse(0,12,17,7,0,0,TAU);ctx.fill();ctx.fillStyle=n.role==='hunter'?'#485a54':n.role==='merchant'?'#805a39':'#655b62';ctx.beginPath();ctx.moveTo(-12,10);ctx.lineTo(-9,-12);ctx.lineTo(0,-20);ctx.lineTo(10,-11);ctx.lineTo(13,10);ctx.closePath();ctx.fill();ctx.fillStyle='#c2a177';ctx.beginPath();ctx.arc(0,-20,8,0,TAU);ctx.fill();ctx.fillStyle='#1a2020';ctx.beginPath();ctx.arc(0,-25,9,Math.PI,TAU);ctx.fill();ctx.fillStyle='#eee4cc';ctx.font='12px serif';ctx.textAlign='center';ctx.fillText(n.icon,0,-38);ctx.fillStyle='#e3d2ae';ctx.font='10px Cinzel';ctx.fillText(n.name,0,-49);if(Math.hypot(n.x-player.x,n.y-player.y)<85){ctx.fillStyle='#d5bd85';ctx.font='10px sans-serif';ctx.fillText('E',0,-61)}ctx.restore()}
function drawEnemy(e){const bob=Math.sin(state.time*4+e.seed)*2;ctx.save();ctx.translate(e.x,e.y+bob);ctx.fillStyle='#080e10';ctx.beginPath();ctx.ellipse(0,12,e.r*1.15,7,0,0,TAU);ctx.fill();if(e.attack>.35){ctx.strokeStyle='#e66d58';ctx.globalAlpha=.6;ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,e.r+22,-.9,1.15);ctx.stroke();ctx.globalAlpha=1}if(e.boss){ctx.fillStyle=e.flash?'#f5d2b5':'#54413d';ctx.beginPath();ctx.moveTo(-31,20);ctx.lineTo(-28,-27);ctx.lineTo(-15,-42);ctx.lineTo(15,-42);ctx.lineTo(30,-23);ctx.lineTo(37,18);ctx.closePath();ctx.fill();ctx.fillStyle='#ba4f43';ctx.beginPath();ctx.arc(-12,-34,5,0,TAU);ctx.arc(13,-34,5,0,TAU);ctx.fill();ctx.fillStyle='#d0b38b';ctx.beginPath();ctx.moveTo(-18,-35);ctx.lineTo(-25,-56);ctx.lineTo(-8,-43);ctx.moveTo(18,-35);ctx.lineTo(26,-56);ctx.lineTo(8,-43);ctx.fill();ctx.fillStyle='#574b44';ctx.fillRect(-39,-6,12,42);ctx.fillRect(28,-6,12,42);ctx.fillStyle='#855b42';ctx.save();ctx.rotate(Math.sin(state.time*4)*.1);ctx.fillRect(28,-3,54,9);ctx.restore()}else{ctx.fillStyle=e.flash?'#ecd8b4':e.name.toLowerCase().includes('lobo')?'#677878':e.name.includes('Samurái')?'#594b46':e.name.includes('Espíritu')||e.name.includes('Yōkai')?'#667d79':'#64534a';ctx.beginPath();ctx.ellipse(0,-2,e.r*.75,e.r,0,0,TAU);ctx.fill();ctx.fillStyle='#d7bc83';ctx.fillRect(-7,-8,3,2);ctx.fillRect(4,-8,3,2);if(e.name.includes('Samurái')){ctx.fillStyle='#4b3b32';ctx.fillRect(-15,-17,30,7);ctx.fillStyle='#d9b866';ctx.fillRect(12,-2,25,2)}}if(e.aggro&&!e.boss){ctx.fillStyle='#9b4239';ctx.fillRect(-15,-e.r-13,30,3);ctx.fillStyle='#c75b4b';ctx.fillRect(-15,-e.r-13,30*e.hp/e.max,3)}ctx.restore()}
function drawPlayer(){ctx.save();ctx.translate(player.x,player.y);if(player.invuln>0&&Math.floor(state.time*18)%2===0)ctx.globalAlpha=.45;ctx.fillStyle='#0a1112';ctx.beginPath();ctx.ellipse(0,12,16,7,0,0,TAU);ctx.fill();let moving=player.moving?Math.sin(state.time*12)*2:0;ctx.fillStyle=player.flash?'#a75e51':'#d0d2c8';ctx.beginPath();ctx.moveTo(-10,9);ctx.lineTo(-8,-12);ctx.lineTo(0,-21);ctx.lineTo(9,-12);ctx.lineTo(11,10);ctx.closePath();ctx.fill();ctx.fillStyle='#313c40';ctx.fillRect(-9,2,18,8);ctx.fillStyle='#c9a76b';ctx.fillRect(-2,-4,4,10);ctx.fillStyle='#b9a17c';ctx.beginPath();ctx.arc(0,-22,8,0,TAU);ctx.fill();ctx.fillStyle='#222729';ctx.beginPath();ctx.ellipse(0,-26,10,5,0,Math.PI,TAU);ctx.fill();ctx.fillStyle='#303638';ctx.fillRect(-6,9+moving,5,7);ctx.fillRect(3,9-moving,5,7);ctx.strokeStyle='#e1ddc6';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(player.face.x*11,player.face.y*11-6);ctx.lineTo(player.face.x*35,player.face.y*35-6);ctx.stroke();if(player.attack>0){ctx.strokeStyle='#f1d89c';ctx.lineWidth=4;ctx.globalAlpha=.78;ctx.beginPath();let a=Math.atan2(player.face.y,player.face.x);ctx.arc(0,-5,45,a-1.05,a+1.05);ctx.stroke()}ctx.restore()}
function drawPortals(){for(const p of portals()){if(p.to===state.region)continue;let active=state.unlocked.includes(p.to);ctx.save();ctx.translate(p.x,p.y);ctx.globalAlpha=.72;ctx.fillStyle=active?'#d9bf83':'#55585a';ctx.beginPath();ctx.ellipse(0,0,27,42,0,0,TAU);ctx.fill();ctx.fillStyle=active?'#8ab2b0':'#30383a';ctx.beginPath();ctx.ellipse(0,0,21,36,0,0,TAU);ctx.fill();ctx.globalAlpha=.22+Math.sin(state.time*2)*.08;ctx.fillStyle=active?'#d6e5d6':'#222';ctx.beginPath();ctx.ellipse(0,0,16,31,0,0,TAU);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#e3d7b6';ctx.textAlign='center';ctx.font='10px Cinzel';ctx.fillText(p.label,0,-53);ctx.restore()}}
function drawEffects(){for(const p of particles){ctx.globalAlpha=clamp(p.life*2,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,TAU);ctx.fill()}ctx.globalAlpha=1;for(const f of floaters){ctx.globalAlpha=clamp(f.life,0,1);ctx.fillStyle=f.color;ctx.font='12px Cinzel';ctx.textAlign='center';ctx.fillText(f.text,f.x,f.y)}ctx.globalAlpha=1}

